from pathlib import Path
from html import escape
p=Path(__file__).parent
css='''*{box-sizing:border-box}html,body{margin:0;width:1920px;height:1080px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{background:#101416;color:#f1f4f2}.scene{position:absolute;inset:0;padding:60px 72px;background:var(--bg);color:var(--ink)}.quiet{--bg:#101715;--panel:#19211e;--card:#222d27;--ink:#eff5ef;--muted:#b0bdb4;--line:#3d4c42;--accent:#b9e2bf}.focus{--bg:#edeae3;--panel:#fcfbf7;--card:#f0eee7;--ink:#272e2a;--muted:#606c63;--line:#d0d5cb;--accent:#356848}.mission{--bg:#0b1221;--panel:#121e32;--card:#1a2b43;--ink:#edf4ff;--muted:#adbed7;--line:#3a506d;--accent:#8acff5}.eyebrow{font-size:18px;letter-spacing:3px;text-transform:uppercase;color:var(--muted)}h1{font-size:50px;font-weight:550;letter-spacing:-2px;margin:14px 0 12px} .subtitle{font-size:23px;color:var(--muted)}.badge{position:absolute;right:74px;top:74px;font-size:18px;border:1px solid var(--line);border-radius:30px;padding:12px 18px}.desktop{position:absolute;left:72px;top:226px;width:1350px;height:742px;background:var(--panel);border:1px solid var(--line);border-radius:20px;overflow:hidden;box-shadow:0 22px 60px #0002}.chrome{height:58px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:9px;padding:0 22px;font-size:18px}.dot{width:10px;height:10px;border-radius:50%;background:var(--muted);opacity:.65}.brand{margin-left:24px;font-weight:650;letter-spacing:.2px}.right{margin-left:auto;color:var(--muted)}.body{display:flex;height:684px}nav{width:206px;padding:26px 18px;border-right:1px solid var(--line);flex-shrink:0;font-size:19px}nav div{padding:13px 14px;margin-bottom:6px;border-radius:8px;color:var(--muted)}nav .selected{background:var(--card);color:var(--ink)}.navlabel{font-size:14px;letter-spacing:2px;margin-top:30px}.main{padding:30px;flex:1;min-width:0;position:relative}.crumb{font-size:16px;color:var(--muted)}h2{font-size:32px;letter-spacing:-.8px;margin:17px 0 12px;font-weight:550}.pills{display:flex;gap:9px;margin:15px 0 24px}.pill{border:1px solid var(--line);padding:7px 10px;border-radius:7px;font-size:15px;color:var(--muted)}.pill.active{color:var(--accent)}.statement{font-size:24px;line-height:1.45;max-width:720px;margin:16px 0 24px}.steps{display:flex;gap:12px}.step{flex:1;padding:20px 17px;border:1px solid var(--line);border-radius:12px;min-height:130px}.num{color:var(--accent);font-size:17px;margin-bottom:18px}.step strong{display:block;font-size:18px;margin-bottom:9px}.step small{font-size:15px;color:var(--muted)}.rail{width:264px;border-left:1px solid var(--line);padding:30px 22px}.rail h3{font-size:18px;margin:0 0 24px}.event{font-size:16px;line-height:1.5;padding-bottom:24px;color:var(--muted)}.event b{color:var(--ink);font-weight:500;display:block}.composer{position:absolute;bottom:27px;left:30px;right:30px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px;display:flex;align-items:center;gap:18px;font-size:18px}.offline{display:none}.wave{display:flex;align-items:center;height:30px;gap:4px;width:42px}.wave i{width:4px;height:22px;border-radius:3px;background:var(--accent)}.wave i:nth-child(2n){height:12px}.composer small{display:block;font-size:14px;color:var(--muted);margin-top:5px}.key{margin-left:auto;font-size:14px;color:var(--muted)}.state{position:absolute;left:30px;right:30px;top:165px;bottom:126px;padding:25px;background:var(--panel);border:1px solid var(--line);border-radius:12px}.state h3{font-size:24px;margin:0 0 17px}.state p{font-size:20px;line-height:1.5;color:var(--muted);max-width:620px}.action{display:inline-block;margin-top:10px;padding:12px 18px;background:var(--accent);color:var(--bg);font-size:17px;border-radius:9px;font-weight:600}.proof{padding:18px;margin-top:20px;border:1px solid var(--line);background:var(--card);border-radius:9px;font-size:18px}.phone{position:absolute;left:1490px;top:238px;width:350px;height:704px;border:2px solid var(--line);border-radius:40px;padding:22px;background:var(--panel);box-shadow:0 24px 50px #0002}.island{width:105px;height:24px;background:var(--ink);border-radius:20px;margin:0 auto 28px;opacity:.85}.phonebrand{font-size:19px;font-weight:600;margin-bottom:33px}.phone h2{font-size:30px;line-height:1.2;margin:12px 0 20px}.phone p{font-size:19px;line-height:1.5;color:var(--muted)}.phonecard{background:var(--card);border:1px solid var(--line);padding:18px;border-radius:14px;margin-top:22px;font-size:18px;line-height:1.5}.phonecard small{display:block;color:var(--muted);font-size:16px;margin-top:8px}.phonefoot{position:absolute;bottom:28px;font-size:16px;color:var(--muted)}.phone-state{position:absolute;top:120px;left:22px;right:22px;bottom:90px;background:var(--panel)}.footer{position:absolute;bottom:44px;left:76px;font-size:18px;color:var(--muted)}.focus nav{display:none}.focus .main{flex:0 0 530px;border-right:1px solid var(--line)}.focus .rail{width:auto;flex:1;border:0;padding:35px}.focus .rail:after{content:"HARBOUR STUDIO";display:block;margin-top:30px;height:210px;background:#dde6db;border-radius:10px;padding:30px;color:#375443;letter-spacing:5px;font-size:27px}.focus .statement{font-size:29px}.focus .steps{display:block}.focus .step{min-height:0;padding:12px 16px;margin-bottom:10px}.focus .step .num,.focus .step small{display:none}.focus .step strong{margin:0}.focus .state{top:165px}.mission nav{width:100px;font-size:14px;padding:24px 8px}.mission nav div{padding:12px 4px}.mission .navlabel{display:none}.mission .rail{display:none}.mission .main{padding:30px 36px}.mission .steps{gap:20px}.mission .step{min-height:222px;background:var(--card);padding:25px}.mission .step strong{font-size:24px}.mission .step small{font-size:18px;line-height:1.5}.mission .composer{left:180px;right:180px;border-radius:30px}.mission .state{left:36px;right:36px;top:165px}.mission .statement{max-width:none;font-size:23px}.focus .action{color:#fff}'''
concepts=[('quiet','01 / Quiet workspace','A calm home for serious work.','Tasks'),('focus','02 / Focus companion','Conversation on one side. The work on the other.','Assistant'),('mission','03 / Mission canvas','See parallel work. Stay in command.','Mission')]
parts=[]
for n,(kind,title,sub,selected) in enumerate(concepts):
 ident='scene'+str(n)
 nav=''.join(f'<div class="{"selected" if x==selected else ""}">{x}</div>' for x in [selected,'Inbox','Projects','Sessions','Memory'])
 steps=''.join(f'<div class="step"><div class="num">0{i+1} / {s}</div><strong>{t}</strong><small>{d}</small></div>' for i,(s,t,d) in enumerate([('CONTEXT','Understand the brief','Email + client folder'),('BUILD','Create the launch pack','Isolated project session'),('REVIEW','Verify and prepare','Private proof document')]))
 markup=f'''<section id="{ident}" class="scene {kind} clip" data-start="{n*14}" data-duration="14" data-track-index="1"><div class="eyebrow">PANEFORGE / INTERACTION STUDY</div><h1>{title}</h1><div class="subtitle">{sub}</div><div class="badge">Design concept · simulated task data</div><div class="desktop"><div class="chrome"><i class="dot"></i><i class="dot"></i><i class="dot"></i><span class="brand">PaneForge</span><span class="right">Mac workspace &nbsp; · &nbsp; Search ⌘ K</span></div><div class="body"><nav>{nav}<div class="navlabel">CONNECTED</div><div>Mac · Online</div><div>PC · Available</div></nav><main class="main"><div class="crumb">Harbour Studio / New project</div><h2>Prepare the launch pack</h2><div class="pills"><span class="pill active"><span class="connected">● Live connected</span><span class="offline">Voice ended</span></span><span class="pill">Brief.pdf</span><span class="pill">Client folder</span></div><div class="initial"><p class="statement">“Pick up the brief, research the context and prepare everything for my review.”</p><div class="steps">{steps}</div></div><div class="state approval"><div class="eyebrow">YOUR INPUT NEEDED</div><h3>Sign in to continue</h3><p>The client workspace needs your login. Open the browser and sign in yourself. This task will wait here.</p><span class="action">Open sign-in window</span><div class="proof">Other authorised tasks can continue.</div></div><div class="state done"><div class="eyebrow">READY FOR YOUR REVIEW</div><h3>Launch pack prepared</h3><p>Draft copy, project files and a proof document are ready. Nothing has been sent or published.</p><div class="proof">↗ &nbsp; Proof pack &nbsp; · &nbsp; Checks and selected screenshots</div><span class="action">Review deliverables</span></div><div class="composer"><div class="wave">{''.join('<i></i>' for _ in range(6))}</div><div class="voice">I’ll check the brief and show you the plan.<small>Live connected · spend details ↗</small></div><span class="key">End voice</span><span class="offline">Voice ended · task continues</span></div></main><aside class="rail"><h3>{'Project canvas' if kind=='focus' else 'Activity & evidence'}</h3><div class="event"><b>Context attached</b>Brief and client folder</div><div class="event"><b>Provider routing</b>Subscription worker<br>API extras tracked separately</div><div class="event"><b>Approval boundary</b>Review before delivery</div></aside></div></div><div class="phone"><div class="island"></div><div class="phonebrand">Taskdriver <span style="float:right">☰</span></div><div class="initial"><div class="eyebrow">YOUR WORK, WITH YOU</div><h2>Harbour Studio</h2><p>Continue the conversation from your phone.</p><div class="phonecard">Launch pack<small>Context found · ready to start</small></div></div><div class="phone-state approval"><div class="eyebrow">NEEDS YOU</div><h2>Desktop sign-in</h2><p>This step needs your Mac. The task is waiting safely.</p><div class="phonecard">Continue on Mac<small>Open the relevant task</small></div></div><div class="phone-state done"><div class="eyebrow">READY TO REVIEW</div><h2>Your launch pack is ready.</h2><p>Read the proof and check the deliverables.</p><div class="phonecard">Open proof pack<small>Private draft · not sent</small></div></div><div class="phonefoot">Tasks &nbsp; &nbsp; Assistant &nbsp; &nbsp; Inbox</div></div><div class="footer">Voice → context → sign-in handoff → private proof. &nbsp; Work continues after voice ends.</div></section>'''
 parts.append(markup)
script='''window.__timelines=window.__timelines||{};const tl=gsap.timeline({paused:true});'''
for n in range(3):
 s=f'#scene{n}';t=n*14
 script+=f'''tl.fromTo('{s} .desktop, {s} .phone',{{y:18}},{{y:0,duration:.6,ease:'power2.out'}},{t});tl.set('{s} .approval, {s} .done',{{opacity:0}},0);tl.fromTo('{s} .initial',{{opacity:1}},{{opacity:0,duration:.2}},{t+5});tl.fromTo('{s} .approval',{{opacity:0,y:12}},{{opacity:1,y:0,duration:.3,immediateRender:false}},{t+5.2});tl.to('{s} .approval',{{opacity:0,duration:.2}},{t+9});tl.fromTo('{s} .done',{{opacity:0,y:12}},{{opacity:1,y:0,duration:.3,immediateRender:false}},{t+9.2});'''
 for j in range(6):
  script+=f"tl.fromTo('{s} .wave i:nth-child({j+1})',{{scaleY:.4}},{{scaleY:1,duration:.3,repeat:11,yoyo:true,ease:'sine.inOut'}},{t+j*.05});"
 script+=f"tl.set('{s} .voice, {s} .key, {s} .connected',{{display:'none'}},{t+4.5});tl.set('{s} .offline',{{display:'block'}},{t+4.5});tl.to('{s} .wave',{{opacity:.25,duration:.3}},{t+4.5});"
script+='window.__timelines.main=tl;'
html='<!doctype html><html lang="en"><head><meta charset="utf-8"><script src="assets/gsap.min.js"></script><style>'+css+'</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="42" data-width="1920" data-height="1080">'+''.join(parts)+'</div><script>'+script+'</script></body></html>'
(p/'index.html').write_text(html)
# Interactive local preview uses the exact render composition, with explicit time controls.
gallery='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>PaneForge directions</title><style>*{box-sizing:border-box}body{margin:0;background:#101514;color:#eef4ef;font:18px -apple-system,BlinkMacSystemFont,sans-serif;padding:36px}h1{font-size:38px;margin:0 0 12px}p{color:#b7c6ba;line-height:1.6;max-width:960px}button,a{background:#23342a;color:#d6f0dd;border:1px solid #54705e;border-radius:9px;padding:12px 17px;margin:5px;cursor:pointer;font:inherit}button:focus-visible,a:focus-visible{outline:3px solid #bcdf90}#viewport{width:100%;aspect-ratio:16/9;position:relative;overflow:hidden;margin-top:22px;border-radius:16px}iframe{border:0;width:1920px;height:1080px;transform-origin:top left}input{width:65%}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:28px 0}.grid img{width:100%;border-radius:10px}.grid a{padding:0;border:0;display:block;background:none}.grid h2{font-size:22px}video{width:100%;max-width:1200px}@media(max-width:800px){body{padding:18px}.grid{grid-template-columns:1fr}}</style><h1>One assistant. Three different homes.</h1><a href="workspace.html">New: futuristic workspace &amp; agent fleet ↗</a><a href="branding/index.html">Explore names &amp; logos ↗</a><p>Compare layout and feel using the same fictional task. These are design prototypes, with simulated work and silent voice activity. Choose a direction or mix elements.</p><div><button data-time="1">01 Quiet workspace</button><button data-time="15">02 Focus companion</button><button data-time="29">03 Mission canvas</button><button id="play">Play / pause</button></div><div id="viewport"><iframe src="index.html" title="Animated desktop and Taskdriver concepts"></iframe></div><p><input type="range" min="0" max="41.95" step=".05" value="1" aria-label="Demo time"> <span id="time">1.0 s</span></p><div class="grid">'''
for i,(_,title,sub,_) in enumerate(concepts):gallery+=f'<article><a href="option-{i+1}.png"><img src="option-{i+1}.png" alt="{title} desktop and phone design"></a><h2>{title}</h2><p>{sub}</p></article>'
gallery+='''</div><h2>Rendered motion study</h2><video controls preload="metadata" src="paneforge-directions.mp4"></video><p>Recommendation: Quiet workspace as the daily home, Focus companion for a conversation, Mission canvas when managing several concurrent projects. These could become modes, but validate one primary experience before building all three.</p><script>const frame=document.querySelector('iframe'),view=document.querySelector('#viewport'),slider=document.querySelector('input');let timeline;function size(){frame.style.transform='scale('+view.clientWidth/1920+')'}new ResizeObserver(size).observe(view);frame.onload=()=>{timeline=frame.contentWindow.__timelines.main;timeline.seek(1,false);timeline.eventCallback('onUpdate',()=>{const t=timeline.time();slider.value=t;document.querySelector('#time').textContent=t.toFixed(1)+' s';frame.contentDocument.querySelectorAll('.scene').forEach((el,i)=>el.style.visibility=t>=i*14&&t<(i+1)*14?'visible':'hidden')});timeline.seek(1.01,false)};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>timeline.pause().seek(+b.dataset.time,false));slider.oninput=()=>timeline.pause().seek(+slider.value,false);document.querySelector('#play').onclick=()=>timeline.paused()?timeline.play():timeline.pause();</script></html>'''
gallery=gallery.replace('src="index.html"', 'srcdoc="'+escape(html, quote=True).replace('data-composition-id','data&#45;composition&#45;id')+'"')
(p/'gallery.html').write_text(gallery)
